window.VF1_UNITS = {"10":{"unit":10,"code":"VF1-U10","title":"Body & Lifestyle","startNumber":246,"endNumber":275,"entries":[{"number":246,"term":"balance · work-life balance","sourceTerm":"balance (v,n) · work-life balance (n.phr)","spoken":"balance · work-life balance","ipa":"/ˈbæləns wɝːk laɪf ˈbæləns/","type":"verb · noun","meaning":"cân bằng/sự cân bằng · cân bằng giữa công việc và cuộc sống","definition":"A state in which different parts are properly controlled; healthy division between work and life.","note":"","example":"A clear schedule helps workers balance their duties and keep a healthy work-life balance."},{"number":247,"term":"benefit ~ advantage · benefit from st","sourceTerm":"benefit (n) ~ advantage (n) · benefit (v) from st","spoken":"benefit ~ advantage · benefit from something","ipa":"/ˈbɛnəfɪt æˈdvæntɪdʒ ˈbɛnəfɪt frʌm ˈsʌmθɪŋ/","type":"verb · noun","meaning":"lợi ích nhận được ~ điểm có lợi · được lợi từ điều gì","definition":"An advantage; to gain an advantage from something.","note":"benefit là lợi ích nhận được; advantage là điểm có lợi so với lựa chọn khác. benefit from nghĩa là được lợi từ.","example":"Exercise has many benefits and advantages, and students benefit from doing it regularly."},{"number":248,"term":"breathe · breath","sourceTerm":"breathe (v) · breath (n)","spoken":"breathe · breath","ipa":"/briːð brɛθ/","type":"verb · noun","meaning":"thở · hơi thở","definition":"To take air into the lungs; the air taken in.","note":"","example":"Take a slow breath and breathe calmly."},{"number":249,"term":"contain · container","sourceTerm":"contain (v) · container (n)","spoken":"contain · container","ipa":"/kəˈnteɪn kəˈnteɪnɚ/","type":"verb · noun","meaning":"chứa/đựng · vật/hộp chứa","definition":"To hold something inside; an object used for holding things.","note":"","example":"The container contains clean drinking water."},{"number":250,"term":"cough # fever # rash # flu # allergy","sourceTerm":"cough (v,n) # fever (n) # rash (n) # flu (n) # allergy (n)","spoken":"cough # fever # rash # flu # allergy","ipa":"/kɑːf ˈfiːvɚ ræʃ fluː ˈælɚdʒi/","type":"verb · noun","meaning":"ho/cơn ho # sốt # phát ban # cúm # dị ứng","definition":"A group of different symptoms and conditions: coughing, fever, a skin rash, influenza, and allergy.","note":"cough, fever và rash thường là triệu chứng; flu là bệnh cúm; allergy là phản ứng dị ứng.","example":"The student stayed home with the flu and a fever; the doctor checked whether her cough and rash were signs of an allergy."},{"number":251,"term":"cure a disease · cure for a disease","sourceTerm":"cure (v) a disease · cure (n) for a disease","spoken":"cure a disease · cure for a disease","ipa":"/kjʊr ə dɪˈziːz kjʊr fɔːr ə dɪˈziːz/","type":"verb · noun","meaning":"chữa khỏi bệnh · phương thuốc/cách chữa bệnh","definition":"To make a disease disappear; a treatment that ends a disease.","note":"","example":"Doctors hope to cure the disease, but there is no quick cure for it."},{"number":252,"term":"have an operation ~ have surgery","sourceTerm":"have an operation ~ have surgery","spoken":"have an operation ~ have surgery","ipa":"/hæv æn ˌɑːpɚˈeɪʃən hæv ˈsɝːdʒɚi/","type":"word / phrase","meaning":"phẫu thuật/trải qua ca mổ","definition":"To receive a medical operation.","note":"operation là một ca phẫu thuật đếm được; surgery là hoạt động/lĩnh vực phẫu thuật, thường nói have surgery, không có a.","example":"The patient had an operation, or surgery, on her knee."},{"number":253,"term":"ignore ~ neglect","sourceTerm":"ignore (v) ~ neglect (v)","spoken":"ignore ~ neglect","ipa":"/ˌɪˈɡnɔːr nəˈɡlɛkt/","type":"verb","meaning":"cố tình không chú ý/phớt lờ ~ bỏ bê/xao nhãng","definition":"To pay no attention to; to fail to give proper care.","note":"ignore thường là cố tình không chú ý; neglect là bỏ bê hoặc không chăm sóc đúng trách nhiệm trong một thời gian.","example":"Do not ignore or neglect a small health problem."},{"number":254,"term":"infect · infection · infectious","sourceTerm":"infect (v) · infection (n) · infectious (a)","spoken":"infect · infection · infectious","ipa":"/ˌɪˈnfɛkt ˌɪˈnfɛkʃən ˌɪˈnfɛkʃəs/","type":"verb · noun · adjective","meaning":"lây nhiễm · sự nhiễm trùng/lây nhiễm · có khả năng lây nhiễm","definition":"To pass a disease to someone; disease in the body; able to spread.","note":"","example":"The virus infected three students, and the infection spread because it was infectious."},{"number":255,"term":"injure · injury","sourceTerm":"injure (v) · injury (n)","spoken":"injure · injury","ipa":"/ˈɪndʒɚ ˈɪndʒɚi/","type":"verb · noun","meaning":"làm bị thương · vết thương/chấn thương","definition":"To cause physical harm; physical harm.","note":"","example":"The player injured his ankle, but the injury was not serious."},{"number":256,"term":"recover from a disease","sourceTerm":"recover (v) from a disease","spoken":"recover from a disease","ipa":"/rɪˈkʌvɚ frʌm ə dɪˈziːz/","type":"verb","meaning":"hồi phục, khỏi bệnh","definition":"To return to health after an illness.","note":"","example":"Mai recovered from the flu after a week of rest."},{"number":257,"term":"salty # sour # spicy","sourceTerm":"salty (a) # sour (a) # spicy (a)","spoken":"salty # sour # spicy","ipa":"/ˈsɔːlti ˈsaʊɚ ˈspaɪsi/","type":"adjective","meaning":"mặn # chua # cay","definition":"Having the taste of salt; having a sharp acidic taste; having the hot taste of spices.","note":"salty, sour và spicy chỉ ba vị khác nhau.","example":"The soup is salty, the lemon is sour, and the curry is spicy."},{"number":258,"term":"suffer from st","sourceTerm":"suffer (v) from st","spoken":"suffer from something","ipa":"/ˈsʌfɚ frʌm ˈsʌmθɪŋ/","type":"verb","meaning":"chịu đựng cái gì","definition":"To experience pain, illness, or difficulty.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: suffer (v) from st","example":"Many students suffer from headaches when they do not sleep enough."},{"number":259,"term":"treat · treatment","sourceTerm":"treat (v) · treatment (n)","spoken":"treat · treatment","ipa":"/triːt ˈtriːtmənt/","type":"verb · noun","meaning":"đối xử/chữa trị · cách đối xử/sự điều trị","definition":"To behave towards someone; to give medical care; medical care.","note":"","example":"The doctor treated the patient kindly, and the treatment helped her recover."},{"number":260,"term":"shape · in shape","sourceTerm":"shape (n) · in shape","spoken":"shape · in shape","ipa":"/ʃeɪp ɪn ʃeɪp/","type":"noun","meaning":"hình dáng/vóc dáng · khỏe mạnh/có vóc dáng tốt","definition":"The form of a body; physically healthy.","note":"","example":"Daily exercise helps people stay in shape and improve their body shape."},{"number":261,"term":"go on a diet","sourceTerm":"go on a diet","spoken":"go on a diet","ipa":"/ɡoʊ ɑːn ə ˈdaɪət/","type":"phrase / pattern","meaning":"ăn kiêng","definition":"To follow a controlled eating plan.","note":"","example":"Mai went on a diet to eat less sugar and more vegetables."},{"number":262,"term":"compared to/with sb/st · in comparison with/to sb/st","sourceTerm":"compared to/with sb/st · in comparison with/to sb/st","spoken":"compared to or with somebody or something · in comparison with or to somebody or something","ipa":"/kəˈmpɛrd tuː ɔːr wɪð ˈsʌˌmbɑːdi ɔːr ˈsʌmθɪŋ ɪn kəˈmpɛrəsən wɪð ɔːr tuː ˈsʌˌmbɑːdi ɔːr ˈsʌmθɪŋ/","type":"phrase / pattern","meaning":"được so với ai/điều gì · khi so sánh với ai/điều gì","definition":"When measured or considered against someone or something.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: compared to/with sb/st · in comparison with/to sb/st","example":"Compared with the first meal, the second has less salt; in comparison, it is healthier."},{"number":263,"term":"medicine · medical","sourceTerm":"medicine (n) · medical (a)","spoken":"medicine · medical","ipa":"/ˈmɛdəsən ˈmɛdəkəl/","type":"noun · adjective","meaning":"thuốc/y học · thuộc y tế/y khoa","definition":"A substance used to treat illness; relating to health care.","note":"","example":"The doctor gave me medicine during a medical visit."},{"number":264,"term":"intend to do st · intention · intentional","sourceTerm":"intend (v) to do st · intention (n) · intentional (a)","spoken":"intend to do something · intention · intentional","ipa":"/ˌɪˈntɛnd tuː duː ˈsʌmθɪŋ ˌɪˈntɛntʃən ˌɪˈntɛnʃənəl/","type":"verb · noun · adjective","meaning":"dự định làm gì · ý định · có chủ ý/cố ý","definition":"To plan to do something; a plan; done deliberately.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: intend (v) to do st · intention (n) · intentional (a)","example":"I intend to exercise daily, and this is my intention; missing one day was not intentional."},{"number":265,"term":"reduce · reduction","sourceTerm":"reduce (v) · reduction (n)","spoken":"reduce · reduction","ipa":"/rəˈduːs rəˈdʌkʃən/","type":"verb · noun","meaning":"giảm/cắt giảm · sự/mức giảm","definition":"To make smaller; the act of making smaller.","note":"","example":"The school reduced sugar in lunches, and the reduction improved the menu."},{"number":266,"term":"sensible # sensitive","sourceTerm":"sensible (a) # sensitive (a)","spoken":"sensible # sensitive","ipa":"/ˈsɛnsəbəl ˈsɛnsətɪv/","type":"adjective","meaning":"hợp lí/biết suy xét # nhạy cảm","definition":"Reasonable and practical; easily affected.","note":"Chú ý cặp đối lập hoặc điểm khác nhau được đánh dấu trong danh sách. Cách kết hợp: sensible (a) # sensitive (a)","example":"It is sensible to protect sensitive skin from strong sunlight."},{"number":267,"term":"addicted to st · addiction · addictive","sourceTerm":"addicted (a) to st · addiction (n) · addictive (a)","spoken":"addicted to something · addiction · addictive","ipa":"/əˈdɪktɪd tuː ˈsʌmθɪŋ əˈdɪkʃən əˈdɪktɪv/","type":"noun · adjective","meaning":"nghiện điều gì · sự nghiện · gây nghiện","definition":"Unable to stop using something; dependence; likely to cause dependence.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: addicted (a) to st · addiction (n) · addictive (a)","example":"Some people become addicted to games because they are addictive; this addiction can affect study."},{"number":268,"term":"allergy · allergic to st","sourceTerm":"allergy (n) · allergic (a) to st","spoken":"allergy · allergic to something","ipa":"/ˈælɚdʒi əˈlɝːdʒɪk tuː ˈsʌmθɪŋ/","type":"noun · adjective","meaning":"dị ứng · bị dị ứng với điều gì","definition":"A harmful physical reaction; affected by an allergy.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: allergy (n) · allergic (a) to st","example":"Mai has a nut allergy and is allergic to peanuts."},{"number":269,"term":"combine A with B · combination","sourceTerm":"combine (v) A with B · combination (n)","spoken":"combine A with B · combination","ipa":"/ˈkɑːmbaɪn ə wɪð biː ˌkɑːmbəˈneɪʃən/","type":"verb · noun","meaning":"kết hợp một thứ với thứ khác · sự/sự vật kết hợp","definition":"To join two things together; things joined together.","note":"","example":"Combine rice with vegetables to make a healthy combination."},{"number":270,"term":"complain to sb about st · complaint","sourceTerm":"complain (v) to sb about st · complaint (n)","spoken":"complain to somebody about something · complaint","ipa":"/kəˈmpleɪn tuː ˈsʌˌmbɑːdi əˈbaʊt ˈsʌmθɪŋ kəˈmpleɪnt/","type":"verb · noun","meaning":"phàn nàn với ai về điều gì · lời/sự phàn nàn","definition":"To express dissatisfaction to someone; a statement of dissatisfaction.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: complain (v) to sb about st · complaint (n)","example":"The patient complained to the doctor about pain, and the doctor recorded the complaint."},{"number":271,"term":"recipe · ingredient","sourceTerm":"recipe (n) · ingredient (n)","spoken":"recipe · ingredient","ipa":"/ˈrɛsəpi ˌɪˈnɡriːdiənt/","type":"noun","meaning":"công thức nấu ăn · nguyên liệu","definition":"Instructions for preparing food; one item used in a dish.","note":"","example":"The recipe lists every ingredient needed for the soup."},{"number":272,"term":"cut down on st ~ reduce st","sourceTerm":"cut down on st ~ reduce st","spoken":"cut down on something ~ reduce something","ipa":"/kʌt daʊn ɑːn ˈsʌmθɪŋ rəˈduːs ˈsʌmθɪŋ/","type":"phrasal verb","meaning":"cắt giảm điều gì","definition":"To reduce the amount of something.","note":"cut down on nghĩa là giảm lượng/tần suất; reduce + tân ngữ trực tiếp.","example":"Students should cut down on sugary drinks and reduce the amount of sugar they eat."},{"number":273,"term":"get over st ~ overcome st","sourceTerm":"get over st ~ overcome st","spoken":"get over something ~ overcome something","ipa":"/ɡɛt ˈoʊvɚ ˈsʌmθɪŋ ˈoʊvɚˌkʌm ˈsʌmθɪŋ/","type":"phrasal verb","meaning":"hồi phục/vượt qua bệnh hoặc cú sốc ~ khắc phục/chinh phục khó khăn","definition":"To recover from illness or overcome difficulty.","note":"get over thường là hồi phục sau bệnh/cú sốc; overcome nhấn mạnh vượt qua thành công một khó khăn.","example":"Mai got over the flu and overcame the weakness that followed it."},{"number":274,"term":"go off","sourceTerm":"go off","spoken":"go off","ipa":"/ɡoʊ ɔːf/","type":"phrasal verb","meaning":"(thức ăn) bị ôi, thiu, hỏng","definition":"To become spoiled and unsafe to eat.","note":"","example":"The milk went off because it was left outside the fridge."},{"number":275,"term":"put on weight ~ gain weight >< lose weight","sourceTerm":"put on weight ~ gain weight >< lose weight","spoken":"put on weight ~ gain weight >< lose weight","ipa":"/pʊt ɑːn weɪt ɡeɪn weɪt luːz weɪt/","type":"phrasal verb","meaning":"tăng cân >< giảm cân","definition":"To gain body weight; to reduce body weight.","note":"put on weight và gain weight nghĩa là tăng cân; lose weight nghĩa là giảm cân.","example":"Nam wants to put on weight, or gain weight, while his brother wants to lose weight."}],"pronunciationFocus":[{"entryNumber":248,"points":[{"category":"common-error","note":"breathe có nguyên âm dài /iː/ và âm cuối /ð/; breath có /ɛ/ và âm cuối /θ/"},{"category":"final-sound","note":"Phân biệt rõ âm hữu thanh /ð/ trong breathe và âm vô thanh /θ/ trong breath"}]},{"entryNumber":250,"points":[{"category":"common-error","note":"Trong cough, phần -gh được đọc là /f/"},{"category":"final-sound","note":"cough kết thúc bằng /f/, còn rash kết thúc bằng /ʃ/"}]},{"entryNumber":252,"points":[{"category":"word-stress","note":"operation nhấn vào âm tiết chứa /eɪ/; surgery nhấn âm đầu"}]},{"entryNumber":254,"points":[{"category":"word-stress","note":"infect, infection và infectious đều nhấn âm tiết thứ hai"}]},{"entryNumber":263,"points":[{"category":"common-error","note":"medicine có dạng /ˈmɛdəsən/, gồm ba âm tiết và nhấn âm đầu"}]},{"entryNumber":271,"points":[{"category":"word-stress","note":"recipe nhấn âm đầu; ingredient nhấn vào /ˈɡriː/"}]},{"entryNumber":273,"points":[{"category":"linking","note":"Trong get‿over, nối /t/ cuối get sang nguyên âm /oʊ/ của over"}]}]}};
